package kr.closeforyou.servicetest

/** Accept only the sixteen enum-derived fields; never echo malformed IPC or arbitrary text. */
internal object CollectionDiagnosticOutput {
    private val labels = listOf("BLOCK", "STEP", "DETAIL", "TREE", "FIELD", "CAUSE", "RELATED", "FRAME", "OP", "EXCEPTION", "NODE_RECT", "NODE_VISIBILITY", "NODE_ANCESTRY", "NODE_ROLE", "WINDOW_BOUNDS_AGE", "TRIGGER")
    // Deliberately fail closed for future/unknown codes; uppercase user strings are not enums.
    private val allowed = listOf(
        setOf("NO_CONSENT", "APP_NOT_ALLOWED", "PROTECTED_APP", "PASSWORD", "EDITABLE_FIELD", "SENSITIVE_CONTENT", "SYSTEM_WINDOW", "UNREADABLE_TREE", "TRUNCATED_TREE", "PAUSED"),
        setOf("ROOT", "PACKAGE_GATE", "WINDOWS", "GEOMETRY", "PROTECTION_PASS", "SNAPSHOT_PASS"),
        setOf("NONE", "ROOT_UNAVAILABLE", "ROOT_PACKAGE_UNAVAILABLE", "PACKAGE_GATE", "WINDOW_LIST_UNAVAILABLE", "TARGET_MISSING", "TARGET_NOT_APPLICATION", "NON_APPLICATION_FOCUS", "FOREIGN_APPLICATION", "SECONDARY_DISPLAY", "TREE_PROTECTION", "COLLECTION_FAILED", "DISPLAY_GEOMETRY_UNCERTAIN"),
        setOf("NONE", "TARGET", "SAME_APP_BACKGROUND"),
        setOf("NONE", "NODE_PACKAGE", "PASSWORD_FLAG", "EDITABLE_FLAG", "INPUT_TYPE", "TEXT", "CONTENT_DESCRIPTION", "VIEW_ID", "CLASS_NAME", "ERROR", "HINT", "PANE_TITLE", "TOOLTIP", "STATE_DESCRIPTION"),
        setOf("NONE", "ROOT_GUARD", "PACKAGE_GUARD", "WINDOW_GUARD", "GEOMETRY_GUARD", "COLLECTION_EXCEPTION", "PACKAGE_MISMATCH", "PASSWORD_FLAG", "PASSWORD_INPUT_TYPE", "EDITABLE_FLAG", "NON_ZERO_INPUT_TYPE", "SENSITIVE_TEXT", "UNCERTAIN_TEXT", "NODE_TEXT_LIMIT", "TOTAL_TEXT_LIMIT", "NODE_COUNT_LIMIT", "DEPTH_LIMIT", "TIME_LIMIT", "CHILD_COUNT_LIMIT", "MISSING_CHILD", "MALFORMED_NODE_BOUNDS"),
        setOf("NONE", "APPLICATION", "INPUT_METHOD", "ACCESSIBILITY_OVERLAY", "SYSTEM", "OTHER"),
        setOf("UNAVAILABLE", "VERIFIED", "EMPTY", "OFFSET", "SIZE_MISMATCH", "DISPLAY_CHANGED"),
        setOf("NONE", "UNCLASSIFIED", "ROOT_READ", "ROOT_METADATA", "WINDOWS_READ", "WINDOW_METADATA", "WINDOW_ROOT_READ",
            "SCREEN_GEOMETRY", "COORDINATE_CHECK", "TREE_BUDGET", "CHILD_COUNT_READ", "CHILD_READ", "CHILD_RELEASE",
            "NODE_PACKAGE_READ", "NODE_FIELD_READ", "NODE_FIELD_CHECK", "NODE_TEXT_READ", "NODE_TEXT_CHECK", "NODE_BOUNDS_READ", "NODE_BOUNDS_DTO", "NODE_BOUNDS_VALIDATE", "NODE_ACTION_READ",
            "NODE_ACTIONS_DTO", "NODE_PROPERTIES_READ", "NODE_DTO", "TEXT_BUDGET", "DIGEST_INITIALIZE", "STRUCTURE_FIELDS", "STRUCTURE_HASH", "CONTENT_HASH",
            "APPLICATION_HASH", "OUTLINE_HASH", "OUTLINE_PROPERTIES_READ", "OUTLINE_DTO", "DIGEST_FINALIZE", "TOKEN_DTO", "SNAPSHOT_DTO", "DETECTION_FRAME_DTO"),
        setOf("NONE", "SECURITY", "ILLEGAL_ARGUMENT", "ILLEGAL_STATE", "INDEX_OUT_OF_BOUNDS", "UNSUPPORTED_OPERATION",
            "NULL_POINTER", "CLASS_CAST", "DIGEST_UNAVAILABLE", "OTHER_EXCEPTION"),
        setOf("UNOBSERVED", "ORDERED", "EMPTY_X", "EMPTY_Y", "EMPTY_BOTH", "REVERSED_X", "REVERSED_Y", "REVERSED_BOTH"),
        setOf("UNOBSERVED", "VISIBLE", "NOT_VISIBLE", "READ_FAILED"),
        setOf("UNOBSERVED", "SCROLL_ANCESTOR", "NO_SCROLL_ANCESTOR"),
        setOf("UNOBSERVED", "ROOT", "DESCENDANT"),
        setOf("UNOBSERVED", "UNSUPPORTED", "UNKNOWN", "WITHIN_ONE_SECOND", "OLDER", "READ_FAILED"),
        setOf("UNOBSERVED", "WINDOW_CHANGED", "CONTENT_CHANGED", "FULL_SCREEN_TRANSITION"),
    )
    fun format(encoded: String): String {
        val values = encoded.split(':')
        if (values.size != labels.size || values.withIndex().any { (index, value) -> value !in allowed[index] })
            return "COLLECTION_DIAGNOSTIC_INVALID"
        return labels.zip(values).joinToString(";") { (label, value) -> "$label=$value" }
    }
}
